INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(4700, 0, 47, 0, 0, 0, 'The Hinterlands', 'The Hinterlands is a wild country of forested hills, high crags and rushing rivers northeast of Tarren Mill, running east to the cliffs above the Forbidding Sea. Long ago it lay at the heart of the Amani empire, and the forest trolls raised great cities here whose ruins still crown the hills. Three troll tribes remain, and they share little but their blood: the Vilebranch, cannibals who serve the blood god Hakkar from their fortress of Jintha''Alor; the Witherbark of Shadra''Alor, who worship a spider god; and the small Revantusk tribe, clinging to the eastern coast. Into this troll country came the Wildhammer dwarves, who left Grim Batol after their war with the Dark Irons, built Aerie Peak and bonded with the gryphons of the crags. The trolls call them squatters on ancestral land. Between the two lie an old Horde base lost to oozes, a lodge of high elves, and a great tree where green dragons guard a door into the Emerald Dream.', 'warcraft.wiki.gg/wiki/The_Hinterlands (Amani heart, great troll cities, Wildhammer arrival, tribes, Skulk Rock, Seradane); quest 2932 description (northeast of Tarren Mill); quest 7844 description (three tribes, Vilebranch feed on trolls and humanoids); quest 2936 description (Witherbark worship a spider god); quest 9470 description (trolls view Wildhammers as squatters); page_text 1927-1928 (War of the Three Hammers: Grim Batol uninhabitable, Aerie Peak, gryphons)'),
(4701, 1, 47, 1, 0, 0, 'Aerie Peak', 'Aerie Peak is the home of the Wildhammer clan, raised on a crag in the western Hinterlands after the clan found Grim Batol tainted and refused King Bronzebeard''s offer of a home within his borders. Unlike their cousins, the Wildhammers built above ground, and at the crest of the town stands the great gryphon aviary kept by Gryphon Master Talonaxe. From here High Thane Falstad Wildhammer rules his people. Wildhammer sentries keep watch beside trained razorbeak gryphons, for the trolls that choke the surrounding hillsides are never far away.', 'page_text 1927-1928 (Grim Batol uninhabitable, Bronzebeard offer refused, Aerie Peak founded); warcraft.wiki.gg/wiki/Aerie_Peak (built above ground, aviary at its crest, Falstad rules from the top); quest 1450 description (Gryphon Master Talonaxe inside the Aerie Peak Aviary); quest 9470 description (trolls attack the gryphon aeries); npc_text 8847 (Rualeth awaiting an audience); warcraft.wiki.gg/wiki/Ambassador_Rualeth (draenei); zone_areas: area 348 holds Falstad 5635, Talonaxe 5636, Rualeth 17223, Wildhammer Sentry 7865, Trained Razorbeak 2657; page_text 1931 (took to living above ground on the slopes of Aerie Peak); quest 2880 description (foul trolls that choke the hillsides)'),
(4702, 1, 47, 2, 0, 0, 'Wildhammer Keep', 'At the far end of the mountain from the aviary stands Wildhammer Keep, home to the town''s inn and tavern, where Innkeeper Thulfram bids guests pull up a chair, for there are stories to tell and kegs to empty. A history of the War of the Three Hammers is kept here, recounting how the clan came to these hills. Outsiders get a blunt welcome. Fraggar Thundermantle insists the Wildhammers are no part of the Alliance and judge strangers by deeds alone, asking newcomers for troll necklaces or a hand in clearing the oozes from Skulk Rock. The master animal handler Agnar Beastamer keeps his trade here too.', 'warcraft.wiki.gg/wiki/Aerie_Peak (Wildhammer Keep at the other end of the mountain); npc_text 823 (Innkeeper Thulfram); gameobject 175739 War of the Three Hammers (page_text 1914-1931); quests 2877, 2880 descriptions (Fraggar: we are NOT part of the Alliance); quests 3843, 4297, 4298 (Agnar Beastamer, master animal handler, sprite darter egg; quest 3843 is a Feralas quest); zone_areas: area 349 holds Thulfram 7744, Truk Wildbeard 4782, Fraggar 7884, Agnar 9660'),
(4703, 1, 47, 3, 0, 0, 'Featherbeard''s Hovel', 'South of Aerie Peak, alone among the hills of the western Hinterlands, stands Featherbeard''s Hovel, the small home of a dwarf of that name. A few chairs wait inside, but whoever calls at the door finds no one at home. The hills around it belong to the Silvermane wolves, mangy packs that range close about the house, and among them prowls a rarely seen old wolf called Old Cliff Jumper.', 'quest 9469 description (Featherbeard revered, gryphon training, wisdom; residence to the south); npc_text 8847 (favors closer ties with the Alliance); quest 9476 description (journal entries); gameobject 181649 Featherbeard''s Journal at 49,-2092 (Aerie Peak at 266,-2029); zone_areas: area 1880 holds Old Cliff Jumper 8211 (rare, family wolf), Mangy Silvermane; zone_areas: area 1880 holds three Wooden Chairs, Mangy Silvermane x2, Old Cliff Jumper 8211, Featherbeard''s Journal 181649'),
(4704, 1, 47, 4, 0, 0, 'Quel''Danil Lodge', 'Quel''Danil Lodge is a high elven outpost in the woods east of Aerie Peak, held by the Highvale elves. It serves as a center of communication for the high elves of the Hinterlands, whose ambassadors seek ties with other races and share what they know of the Witherbark trolls, and the records, notes and reports of that work are kept inside. The Highvale have made friends of the Wildhammers, and the Revantusk hate them for it. Scouts, marksmen, outrunners and rangers guard the grounds, among them a rarely seen elf named Jalinde Summerdrake, and a captured Witherbark troll called Rin''ji has been kept caged within.', 'quest 2995 description (center of communication, ambassadors, knowledge of the Witherbark, documents kept at the lodge); quest 7841 description (Wildhammer working with the high elves); warcraft.wiki.gg/wiki/Quel''Danil_Lodge (Wildhammer alliance angered the Revantusk); quest 2742 description; zone_areas: area 350 holds Highvale Scout/Marksman/Outrunner/Ranger, Jalinde Summerdrake 8214 (rare), Rin''ji 7780, Rin''ji''s Cage, Highvale Records/Notes/Report; DB: lodge at 263,-2758, east of Aerie Peak 266,-2029'),
(4705, 1, 47, 5, 0, 0, 'Shindigger''s Camp', 'East of Aerie Peak, a short walk from the Quel''Danil Lodge, two drinkers share a small camp. Rhapsody Shindigger was once the finest gryphon rider at Aerie Peak until his love of liquor cost him his place, and he now brews his own malt here. Beside him sits Gilveradin Sunchaser, a high elf who owes nothing to the Alliance and holds that drink transcends treaties and borders; it is said he can name any wine, vintage and all, by smell alone. He keeps the original packaging for Hinterlands Honey Ripple, a vintage no longer to be had, whose last bottles lie in crates at the old Horde base near Skulk Rock.', 'quest 1451 description (Rhapsody, brew camp east of Aerie Peak); warcraft.wiki.gg/wiki/Rhapsody_Shindigger (moonshine camp, Rhapsody Malt); quest 649 description and reward text (cannot get fine ripple like that anymore; Gilveradin not a part of the Alliance); quest 650 description and reward text (names any wine by smell; alcohol transcends treaties and alliances); quest 77 description and reward text (packaging, crates near Skulk Rock); zone_areas: area 1881 holds Rhapsody 5634 and Gilveradin 7801'),
(4706, 1, 47, 6, 0, 0, 'Zun''watha and Hiri''watha', 'In the hills south of Aerie Peak and the Quel''Danil Lodge lie the lesser villages of the Witherbark trolls: the ruins of Zun''watha, held by Witherbark scalpers and zealots, and Hiri''watha, home to hideskinners and venombloods. Both keep stores of bottled green venom, in such numbers that the tribe must prize it, and both keep cages for captives; when the gryphon Sharpbeak went missing, it was these cages the Wildhammers set out to search. The Witherbark once stood with the Horde before turning on Thrall, and the Darkspear troll Nimboya of Grom''gol wants a pike laden with Witherbark skulls driven into one of these villages as a warning. A troll called Zul''arek Hatefowler is sometimes seen at either.', 'warcraft.wiki.gg/wiki/Witherbark_tribe (Hiri''watha village, Zun''watha ruins; Zul''arek associated with Zun''watha); quest 2933 description (number of venom bottles in this village); quest 2988 description (cages in the two Witherbark villages); quest 2932 description (Witherbarks betrayed Thrall; pike at Hiri''watha or Zun''watha); zone_areas: area 352 Witherbark Scalper/Zealot, First and Second Witherbark Cage, Venom Bottles, Zul''arek Hatefowler 8219; area 1885 Witherbark Hideskinner/Venomblood, Third Witherbark Cage, Venom Bottle, Zul''arek; DB: cages at -43,-2470 and -4,-2806, south of Aerie Peak 266,-2029 and the lodge 263,-2758; creature 2497 Nimboya spawned at Grom''gol, faction template 126 (Darkspear Trolls)'),
(4707, 1, 47, 7, 0, 0, 'Bogen''s Ledge', 'Bogen''s Ledge is a cave in the hills of the southwestern Hinterlands, west of Shadra''Alor, the temple city of the Witherbark trolls. A few Witherbark sadists keep to the ground before it, and vicious owlbeasts hunt the slopes outside, with now and then a Silvermane wolf among them, while wildkin feathers lie scattered in the grass. Sungrass and golden sansam grow among the rocks, and veins of iron, mithril and truesilver run through the stone.', 'quest 9470 description and reward text (Mai''jin, cave at Bogen''s Ledge west of Shadra''Alor, pet spider Tcha''kaz); quest 9476 description (Featherbeard suspected Mai''jin); zone_areas: area 1887 holds Witch Doctor Mai''jin 17235, Tcha''kaz 17236 (family spider), Witherbark Sadist, Vicious Owlbeast; warcraft.wiki.gg/wiki/Bogen''s_Ledge (a cave in the southwestern Hinterlands); zone_areas: area 1887 holds Witherbark Sadist x2, Vicious Owlbeast x6, Silvermane Wolf x1, Wildkin Feather x2, Sungrass, Golden Sansam, Iron, Mithril and Truesilver Deposits'),
(4708, 1, 47, 8, 0, 0, 'Shadra''Alor', 'Shadra''Alor is the temple city of the Witherbark trolls, a cluster of old temples in the southern Hinterlands where the tribe keeps the worship of its spider god. Broodguard spiders nest among the ruins beside Witherbark sadists and callers, and a rarely seen troll called Witherheart the Stalker prowls among them. Not every troll here is Witherbark. An Atal''ai priest, cast out of the Temple of Atal''Hakkar in the Swamp of Sorrows, now lives among them in exile.', 'warcraft.wiki.gg/wiki/Shadra''Alor (main Witherbark settlement, Shadra summoned there); warcraft.wiki.gg/wiki/Witherbark_tribe (Shadra a spider loa); quest 9475 description (map of Shadra''Alor and its three temples); quest 9476 reward text (bones upon the altar); quest 2936 description (most potent venom from their god); quest 2934 description (spiders near Shadra''Alor); quest 1429 and 1446 descriptions (Atal''ai exile with the Witherbark); zone_areas: area 353 holds Witherbark Broodguard 2686 (family spider), Sadist, Caller, Gryphon Egg x10, Featherbeard''s Remains, Atal''ai Exile 5598; zone_areas: area 353 holds Witherheart the Stalker 8218 (rare, humanoid, Vilebranch faction template 795)'),
(4709, 1, 47, 9, 0, 0, 'Valorwind Lake', 'Valorwind Lake lies among the hills of the central Hinterlands, its banks roamed by primitive owlbeasts and Silvermane howlers. Its waters hide a curiosity sought from as far away as Gadgetzan: the Violet Tragan, a mushroom found nowhere but beneath the surface of this one small lake. Sprinkle of Gadgetzan swears by it as a secret ingredient that can turn even the most horrid brew into something edible. Those who go looking for it had best be able to hold their breath.', 'quest 2641 description and request text (Violet Tragan, small lake in the Hinterlands, only found underwater); zone_areas: area 1883 holds Violet Tragan x6, Primitive Owlbeast x13, Silvermane Howler x5'),
(4710, 1, 47, 10, 0, 0, 'The Altar of Zul', 'The Altar of Zul is a troll altar on the western edge of Vilebranch territory, a tribe known for its sacrifices. Soothsayers, scalpers and axe throwers guard its slopes with their wolves, and a berserker called Retherokk is sometimes seen among them. At the top wait two keepers, Qiaga and Morta''gya. Qiaga carries a sacred mallet which, once consecrated at the altar atop Jintha''Alor, becomes a mallet able to call forth the demigod Gahz''rilla in distant Zul''Farrak.', 'quest 2989 description and reward text (western edge of Vilebranch territory, known for performing sacrifices); warcraft.wiki.gg/wiki/Altar_of_Zul (Qiaga on top, Morta''gya before the Cataclysm, Sacred Mallet); warcraft.wiki.gg/wiki/Jintha''Alor (ritual at the altar at the top of the city made the Mallet of Zul''Farrak, used to summon Gahz''rilla); creature_loot_template: Qiaga 7996 drops Sacred Mallet 9241 at 100 percent; gameobject 142180 Jintha''Alor Alter spell focus; zone_areas: area 355 holds Vilebranch Soothsayer, Axe Thrower, Scalper, Wolf Pup, Retherokk the Berserker 8216, Qiaga 7996, Morta''gya 8636'),
(4711, 1, 47, 11, 0, 0, 'Jintha''Alor', 'Jintha''Alor, named for an ancient Amani leader, is the second largest forest troll city after Zul''Aman and the capital of the Vilebranch. From its heights Vile Priestess Hexx serves Hakkar the blood god, and vessels of tainted blood scattered through the city fill the tribe with his ferocity and madness. Blood drinkers, soul eaters, shadow hunters and Hexx''s Aman''zasi guard hold the upper city, where captives are kept for sacrifice. Near the top lie a refuse pit full of oozes and a wolf den, and in a cave behind the amphitheater at the summit rests an ancient egg, a relic of the days when trolls ruled vast empires.', 'warcraft.wiki.gg/wiki/Jintha''Alor (named after Jintha, second largest forest troll city after Zul''Aman, Vilebranch capital, Hexx follower of Hakkar); quest 7850 description (vessels of tainted blood, foul magic of the blood god, ferocity and madness); quest 7845 description (Torntusk held atop for sacrifice); quest 7849 description (refuse pit of oozes and wolf den near the top); quest 4787 description (Ancient Egg in a cave behind the amphitheater; can hold the essence of Hakkar); quest 2993 description (Sharpbeak caged high on a cliff at the top); zone_areas: area 354 holds Vilebranch Blood Drinker, Shadow Hunter, Aman''zasi Guard, Soul Eater, Berserker, Raiding Wolf, Jade Sludge, Vile Priestess Hexx 7995, Elder Torntusk 14757, Sharpbeak 8023, Vessel of Tainted Blood x28; quest 4787 description (relic of a time when trolls ruled vast empires); gameobject 175889 Ancient Egg spawned on map 0 at -760,-3792'),
(4712, 1, 47, 12, 0, 0, 'Skulk Rock', 'Skulk Rock was a Horde base in the Second War, until the Alliance drove the orcs out and it was left to ruin. Crates of their supplies still lie about, some holding bottles of Hinterlands Honey Ripple, a drink that can no longer be had anywhere else. The rock is now overrun with green sludges and jade oozes, said to be led by a master ooze, and a creature called The Reak is sometimes found there. The Wildhammers have plans for the place and reward any who thin the slime. Not far off, at the head of a river, a gnomish homing robot shaped like a chicken crashed from the sky and waits to be found.', 'warcraft.wiki.gg/wiki/Skulk_Rock (Old Horde base, driven out by the Alliance, abandoned, Honey Ripple left behind); quest 2877 description (Horde abandoned their positions; Wildhammers have plans for the area); quest 77 description (crates at the abandoned Horde base near Skulk Rock; led by some sort of master ooze); quest 649 description (you can''t get fine ripple like that anymore); quest 485 description (OOX-09/HL crashed at the head of the river near Skulk Rock); zone_areas: area 351 holds Jade Ooze x32, Green Sludge x19, The Reak 8212 (rare), Horde Supply Crate x6'),
(4713, 1, 47, 13, 0, 0, 'Agol''watha and Shaol''watha', 'In the northern and eastern hills stand the old troll temples of Agol''watha and Shaol''watha, the first a relic of the Amani empire. Agol''watha is overrun with green sludges and jade oozes, and stray Horde supply crates lie among its stones. Vilebranch scalpers and soothsayers roam the country around these temples, and the Revantusk name them a depraved lot who feed on other trolls. When Vilebranch raiders made off with the tools of the Revantusk smith, a gift from a gnome who once saved his life, the stolen set was spotted near these two temples.', 'warcraft.wiki.gg/wiki/Agol''watha (temple of the late Amani Empire, overrun by sludges); quest 7839 description (tools spotted near the Agol''watha and Shaol''watha temples, northeastern region); quest 7844 description and log (Vilebranch scalpers and soothsayers near Shaol''watha and Agol''watha; depraved, feeding on other trolls); zone_areas: area 1884 holds Green Sludge x15, Jade Ooze x7, Horde Supply Crate x4; area 1917 Slagtree''s Lost Tools; DB: Vilebranch Scalper/Soothsayer groups at 447,-3620 and 220-330,-4100..-4350'),
(4714, 1, 47, 14, 0, 0, 'Seradane', 'In the northeast of the Hinterlands rises Seradane, one of the four great trees whose portals open into the Emerald Dream. The green dragonflight has made the surrounding forest its home. Verdantine oracles, boughguards and tree warders, the dragonspawn of the flight, patrol the glades in bands, and the drakes Rothos and Dreamtracker keep watch nearby, suffering no intruder to come near the portal.', 'warcraft.wiki.gg/wiki/Seradane (northeastern Hinterlands, entrance to the Emerald Dream, Rothos and Dreamtracker, Verdantine patrols in groups of three); warcraft.wiki.gg/wiki/The_Hinterlands (one of four Great Trees guarded by Emerald Dragons); warcraft.wiki.gg/wiki/Lethon; zone_areas: area 356 holds Verdantine Boughguard/Oracle/Tree Warder, Lethon 14888, Rothos 5718, Dreamtracker 12496; creature_template faction 50 for Rothos 5718, Dreamtracker 12496 and the Verdantine (hostile)'),
(4715, 1, 47, 15, 0, 0, 'The Overlook Cliffs', 'The Overlook Cliffs form the eastern edge of the Hinterlands, where the land drops sheer to the Forbidding Sea and the great river of the region pours over the edge in a massive waterfall. Saltwater snapjaws crowd the shore below, led by a thieving turtle called Gammerita, and a giant turtle known as Ironback is sometimes seen. Small islands lie offshore, and one of them is the secret picnic spot of the Revantusk innkeeper Lard. Storms blow in off this coast, and bottles of port lost overboard from a passing ship litter the shallows.', 'warcraft.wiki.gg/wiki/Overlook_Cliffs (eastern shoreline, river ends in a massive waterfall); quest 7816 description (Gammerita leader of the snapjaws, thieving); quest 2742 log and creature_text 7780 (secret on an island at the Overlook Cliffs); quest 7840 description (island to the north); quest 626 (base of the great falls, underneath the water); quest 580 description (storm off the Hinterlands, Pupellyverbos Port overboard); zone_areas: area 307 holds Saltwater Snapjaw x61, Gammerita 7977, Ironback 8213 (rare, family turtle), Rin''ji''s Secret, Cortello''s Treasure, Lard''s Picnic Basket, Pupellyverbos Port x16'),
(4716, 1, 47, 16, 0, 0, 'Revantusk Village', 'On the southeastern coast lies Revantusk Village, home of the Revantusk, smallest and weakest of the region''s three troll tribes. Scorned by the other forest trolls for their loyalty to the Horde, the Revantusk never formally rejoined it under Thrall but keep a pact of friendship with it, and wind riders link the village to Horde lands. Primal Torntusk, mate of the village elder, gives the orders, drummers beat out the rhythm of the village and watchers stand guard. Its folk are a mixed lot: an orc smith named Slagtree, a fisherman schooled by the great angler Nat Pagle, and the big-bellied Lard, who keeps the peace and sells fish.', 'warcraft.wiki.gg/wiki/Revantusk_tribe (southeast coast; attacked by other forest trolls for loyalty to the Horde; declined to rejoin, pact of friendship); warcraft.wiki.gg/wiki/The_Hinterlands (weakest tribe); quests 7845, 7861 (Primal Torntusk, her mate; by order of Primal Torntusk); quest 7839 description (Slagtree a young orc saved by a gnome); npc_text 7241 (Katoom, mentor Nat Pagle); npc_text 7211 (Lard keep peace, sell fish); quest 7840 request text (enormous belly); zone_areas: area 3317 holds Revantusk Watcher x23, Revantusk Drummer x3, Gorkas 4314 Wind Rider Master, Troll Drum Sound Object'),
(4717, 2, 47, 1, 1, 0, 'Falstad Wildhammer', 'Falstad Wildhammer is High Thane of the Wildhammer clan. After the Second War he led a small flight of gryphon riders patrolling the shores of Lordaeron, and it was Falstad and his riders who carried the mage Rhonin and his companions across the Great Sea to Khaz Modan, losing kinsmen to an ambush on the way. He fought in the final battle at Grim Batol that freed the Dragonqueen Alexstrasza. When Kurdran Wildhammer left for Draenor with the Alliance expedition, Falstad stayed behind at Aerie Peak and succeeded him. He has little patience for idle visitors, with trolls, as he puts it, coming out of the woodwork.', 'warcraft.wiki.gg/wiki/Falstad_Wildhammer (patrol flight, Rhonin, ambush, Grim Batol, succeeded Kurdran); quest 1449 reward text (trolls coming out of the woodwork); quest 1450 description; DB: Falstad 5635 spawned in area 348, faction 694'),
(4718, 2, 47, 2, 1, 0, 'Gryphon Master Talonaxe', 'Gryphon Master Talonaxe keeps the great aviary of Aerie Peak and its riders. He has a soft spot for the Explorers'' League, for his father helped the first excavation team that discovered Uldaman, and he once lent his best rider, Rhapsody Shindigger, to the dwarf Brohann Caskbelly for a search from the air, only to let him go afterwards when drink got the better of him. The gryphons are his whole world. Young Sharpbeak, heir of the mighty Swiftwing, has vanished while hunting with his parents, and Talonaxe, sure the trolls took him, will not rest until the youngster is home.', 'quest 1450 reward text (Explorers'' League, father and Uldaman, sent Rhapsody with Brohann); quest 1451 description (had to let him go); quest 2988 description and reward text (Swiftwing''s heir, strength and spirit of the fleet); quest 2994 reward text'),
(4719, 2, 47, 3, 0, 0, 'Rhapsody Shindigger', 'Rhapsody Shindigger was once the finest gryphon rider of Aerie Peak, so trusted that Gryphon Master Talonaxe lent him to the explorer Brohann Caskbelly for a search from the air over the Swamp of Sorrows. But Rhapsody took to liquor the way a gryphon takes to the sky. He came stumbling back from that flight with a troll relic in his pack and a secret he kept to himself, and before long the aviary let him go. He now keeps a small brew camp east of Aerie Peak beside the high elf Gilveradin Sunchaser, where he makes Rhapsody Malt, hiccups through every conversation, and needs a very stiff drink before he will speak of that swamp at all.', 'quest 1451 description; quest 1469 description (keg of stout, fell off, trolls, souvenir); quest 1452 description and request text (Rhapsody Malt); creature_text 5634; warcraft.wiki.gg/wiki/Rhapsody_Shindigger; quest 1469 reward text (he knew about the sinking all along); zone_areas: area 1881 holds Rhapsody 5634 and Gilveradin 7801'),
(4720, 2, 47, 4, 2, 0, 'Primal and Elder Torntusk', 'Elder Torntusk is chieftain of the Revantusk, and Primal Torntusk is his mate. In a bold midnight raid the Vilebranch carried the elder off to Jintha''Alor, and the village''s spies say he is still alive, held prisoner atop the city while Vile Priestess Hexx prepares him as a sacrifice to Hakkar. Primal seeks champions to bring him home, fearing the village could not bear so great a loss. She strikes at the blood god directly too, seeking the dark vessels of tainted blood from Jintha''Alor so that their taint can be removed and the god''s grip loosened.', 'quest 7845 description (my mate taken in a midnight raid); quest 7846 reward text (Revantusk will know your deeds); quest 7850 description and reward text; warcraft.wiki.gg/wiki/Revantusk_tribe (Elder Torntusk the Hinterlands chieftain before Cataclysm)'),
(4721, 2, 47, 5, 2, 0, 'Huntsman Markhor', 'Huntsman Markhor is master huntsman of Revantusk Village, sworn to keep the beasts of the wilds in check: Silvermane wolves, savage owlbeasts, and the razorbeak gryphons he believes the Wildhammers train to kill trolls. He holds that Zul''jin will return one day. His grief is his own. His twin brother Malkhor, captain of the village guard, was taken in the same raid as Elder Torntusk and swiftly executed, his remains thrown to the oozes and wolves of Jintha''Alor. Markhor asks only that the bones be recovered, so that Mystic Yayo''jin can prepare them for a proper burial.', 'npc_text 7242 (Zul''jin shall return; master huntsman); quests 7828, 7829, 7830 descriptions; quest 7849 description and request text; quest 7862 description (Guard Captain Malkhor)'),
(4722, 2, 47, 6, 0, 0, 'Vile Priestess Hexx', 'Vile Priestess Hexx is a priestess of the Vilebranch trolls, and she holds the summit of Jintha''Alor, the tribe''s capital, in the name of Hakkar the blood god. Her Aman''zasi guard stands close about her, and vessels of tainted blood lie scattered through the city below, heavy with the blood god''s ferocity and madness. In battle she wracks her foes with shadow, lays hexes upon them and heals the wounds of her guards, and when her own strength fails she flees to call the tribe to her side.', 'quest 2993 description (high priestess, key to the cage); quest 7845 description (preparing him for a sacrifice to Hakkar); quest 7850 description; quest 7861 description (Aman''zasi elite guard); quest 2994; warcraft.wiki.gg/wiki/Jintha''Alor (follower of Hakkar); smart_scripts 7995 (Shadow Word: Pain, Hex, Heal on friendly, flee for assist at 15 percent); zone_areas: area 354 holds Hexx 7995, Vilebranch Aman''zasi Guard x17 (rank 0), Vessel of Tainted Blood x28; warcraft.wiki.gg/wiki/Jintha''Alor (Vilebranch capital)'),
(4723, 2, 47, 7, 0, 0, 'The Atal''ai Exile', 'In the shadow of Shadra''Alor lives a troll far from home: a priest of the Atal''ai, servants of the blood god in the Temple of Atal''Hakkar in the Swamp of Sorrows. He once thought the high priest Jammal''an a worthy leader, but when he questioned the prophecy that drives his tribe and wondered whether it was nothing but manipulation, he was branded an infidel and cast out, a sentence his people count worse than death. Now he lives among the Witherbark, who do not care for strangers near their home. He craves revenge on Jammal''an. With the prophet gone, he believes, he might yet return to his people; under Jammal''an the Atal''ai face certain destruction.', 'quest 1446 description, request and reward text; quest 1444 description (labeled an infidel, ousted); quest 1429 description (fate worse than death, exiled with the Witherbark); DB: Atal''ai Exile 5598 in area 353, template 35; quest 1446 completion text (hopes of returning to his people)'),
(4724, 2, 47, 8, 2, 0, 'Rin''ji', 'Rin''ji is a Witherbark troll who lost an axe, was captured by the Highvale elves and now sits caged in the Quel''Danil Lodge, under the eyes of its guards. Desperate, Rin''ji begs Horde travelers for rescue, knowing full well that they have little love for the Witherbark, and promises them something in return: a secret, hidden somewhere at the Overlook Cliffs, for whoever helps Rin''ji get out of the lodge alive.', 'quest 2742 description and log; creature_text 7780; quest 2782 description; quest 8273 reward text (Oran: Dark Lady very pleased)'),
(4725, 2, 47, 9, 0, 0, 'Lethon', 'Lethon was once among the most trusted lieutenants of Ysera, Aspect of the green dragonflight, until the nightmare spreading through the Emerald Dream warped him. His scales have darkened and he wields the power of shadow. Now he haunts Seradane, turning on all who come near the portal. Lethon claims to sense the shadow in the hearts of those who face him, and he tears it from them as dark shades that return to their master and mend his wounds.', 'warcraft.wiki.gg/wiki/Lethon (Ysera''s trusted lieutenant, warped by the Nightmare, darkened scales, shades that heal him); creature_text 14888 (I can sense the SHADOW on your hearts); DB: Lethon 14888 spawned at Seradane (753,-4012), area 356'),
(4726, 3, 47, 1, 1, 0, 'Saving Sharpbeak', 'Sharpbeak, son of Swiftwing, the mightiest gryphon of Aerie Peak, vanished a few days ago while hunting with his parents, and Gryphon Master Talonaxe believes the trolls took him. The Witherbark are the likeliest thieves, and their two villages in the hills south of the peak keep cages for their captives, so the search begins there. To the Wildhammers this is no small loss. Sharpbeak is Swiftwing''s heir, the son of the finest gryphon in the aviary, and Talonaxe asks every friend of Aerie Peak to help find him before the trolls can do him harm.', 'quests 2988, 2989, 2990, 2992, 2993, 2994 (descriptions and reward texts); warcraft.wiki.gg/wiki/Jintha''Alor (parents Swiftwing and Keenclaw); warcraft.wiki.gg/wiki/Sharpbeak (son and heir of Swiftwing and Keenclaw)'),
(4727, 3, 47, 2, 1, 8, 'Featherbeard''s Last Flight', 'Ambassador Rualeth, a draenei envoy, has come to Aerie Peak to win the Wildhammers'' friendship for the Alliance, only to find them far warier of outsiders than he was told. While he waits for an audience with the High Thane, he looks for ways to prove good faith: culling the wolf packs that prey on the gryphons, and calling for the death of Witch Doctor Mai''jin, a Witherbark leader blamed for the troll attacks on the aeries. Above all he wants the backing of Featherbeard, the revered gryphon trainer who is said to favor closer ties, and he sends word to the dwarf''s hovel south of the peak.', 'quests 9469, 9470, 9471, 9475, 9476 (descriptions and reward texts); npc_text 8847 (wary of outsiders an understatement; Featherbeard favors closer ties); warcraft.wiki.gg/wiki/Featherbeard; warcraft.wiki.gg/wiki/Ambassador_Rualeth (draenei)'),
(4728, 3, 47, 3, 2, 0, 'Blood at Jintha''Alor', 'The Vilebranch prey on the weaker Revantusk, and their latest raid came at midnight. Elder Torntusk was dragged to the heights of Jintha''Alor, where, the village''s spies say, Vile Priestess Hexx prepares him as a sacrifice to Hakkar, and Guard Captain Malkhor, taken with him, was swiftly executed and his remains thrown to the oozes and wolves. Primal Torntusk seeks champions to bring her mate home, while Huntsman Markhor asks for his twin''s bones. Primal means to turn the fight on Hexx herself as well, seeking the vessels of tainted blood that feed the Vilebranch frenzy and posting a bounty on the priestess and her Aman''zasi guard, and even the empty post of guard captain is offered to whoever can thin the Vilebranch ranks.', 'quests 7845, 7846, 7847, 7849, 7850, 7861, 7862 (descriptions and reward texts); warcraft.wiki.gg/wiki/Vilebranch_tribe (Revantusk chosen as a source of victims)'),
(4729, 3, 47, 4, 2, 0, 'Messages to the Wildhammer', 'The Revantusk have long feuded with the Wildhammers, and Huntsman Markhor claims the dwarves train their gryphons to slay trolls. Now word has come that the Wildhammers are forging new alliances, this time with the high elves of the Quel''Danil Lodge, and the Revantusk cook Otho Moji''ko has decided the dwarves need a message written in the blood of their new friends. Highvale scouts, outrunners, rangers and marksmen are to be cut down and left where they fall as a warning to the Wildhammers: never mess with trolls.', 'quests 7841, 7842, 7843 (descriptions, request and reward texts); quest 7830 description (Wildhammer trains gryphon to slay troll); warcraft.wiki.gg/wiki/Revantusk_tribe (long-standing feud with the Wildhammer)'),
(4730, 3, 47, 5, 2, 0, 'The Spider God', 'In the Witherbark villages of Zun''watha and Hiri''watha lie bottles of a vile green venom, hoarded in such numbers that the trolls must count it very important. Whatever it is, it might interest the Forsaken. In nearby Tarren Mill the Royal Apothecary Society brews poisons for the Dark Lady, and a sample of troll venom is just the sort of thing one of its apothecaries would want to see. What creature yields it, and why the Witherbark guard it so closely, no one in Tarren Mill yet knows.', 'quests 2933, 2934, 2935, 2936, 2937, 2938 (descriptions and reward texts); creature_template 2707 Shadra (family spider); hillsbrad.json 26705 (Tarren Mill: the apothecaries brew for the Dark Lady)');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(4701, 1, 8, 255, 'Since the draenei joined the Alliance, Aerie Peak has had an envoy from the Exodar. Ambassador Rualeth waits here for an audience with the High Thane, and has found that calling the Wildhammers wary of outsiders is quite an understatement: it was a struggle just to present his credentials. He pins his hopes on Featherbeard, a Wildhammer said to favor closer ties with the Alliance.', 'npc_text 8847 (Rualeth awaiting an audience, wary of outsiders an understatement, Featherbeard favors closer ties); warcraft.wiki.gg/wiki/Ambassador_Rualeth (draenei); creature_template 17223 faction 1638 (Exodar); mod-individual-progression optional/sql/world/zz_optional_phasing.sql lists 17223 as npc_ipp_tbc (added in 2.0)'),
(4703, 1, 8, 255, 'Since the draenei came to Aerie Peak, the absent dwarf has been sought out. Featherbeard is revered among the Wildhammers for his skill in training gryphons and for his wisdom, and is said to favor closer ties with the Alliance. His journal still lies in the hovel, its latest pages full of worry over Witherbark raids on the gryphon aeries and a rash of stolen eggs. The last entry names the witch doctor Mai''jin as the one he suspects, and ends with a hurried note that he meant to go to Shadra''Alor himself.', 'quest 9469 description (revered, gryphon training, wisdom) and reward text (journal with recent entries); RewardNextQuest 9476 from the journal, gameobject 181649; quest 9476 description (raids, egg thefts, Mai''jin suspected, Shadra''Alor); npc_text 8847 (favors closer ties with the Alliance)'),
(4707, 1, 8, 255, 'In these days the cave has a tenant. Witch Doctor Mai''jin of the Witherbark trolls shelters inside it, and his pet spider, Tcha''kaz, keeps close at his side. The sadists on the slopes outside stand between the witch doctor and any who would reach him.', 'zone_areas: area 1887 holds Witch Doctor Mai''jin 17235 and Tcha''kaz 17236 (2.0 creature ids), Witherbark Sadist; warcraft.wiki.gg/wiki/Bogen''s_Ledge (before the Cataclysm home to Mai''jin and Tcha''kaz)'),
(4707, 2, 8, 255, 'Mai''jin is no common witch doctor but a leader of the Witherbark, and the trolls'' attacks on the Wildhammer gryphon aeries are laid at his door. The draenei envoy Rualeth at Aerie Peak has asked for his death and that of his spider, hoping that helping to stop the raids will prove the Alliance''s good faith in the eyes of the wary Wildhammers.', 'quest 9470 description (Witherbark leader, cave at Bogen''s Ledge west of Shadra''Alor, attacks on the gryphon aeries, a way to prove ourselves to the Wildhammer)'),
(4708, 1, 0, 255, 'The city''s name holds the god''s own. Her true name is Elortha no Shadra, to be spoken only in whispers, for it carries great weight in the realms of the spirit, and from her the Witherbark draw their most potent venom. Read at the altar of Shadra''Alor, a spell of summoning written in that name will call Shadra herself into the world.', 'quest 2936 description (spider god, most potent venom) and reward text (Elortha no Shadra, speak only in whispers); quest 2937 description (read at the altar of Shadra''Alor to summon Shadra)'),
(4708, 2, 8, 255, 'Not all of the city''s secrets are troll lore. Upon one of its altars lie the broken bones of a dwarf, all that is left of Featherbeard of Aerie Peak, and clutched in his hand was a map of Shadra''Alor and its three temples, marked where the stolen gryphon eggs lie hidden about the ruins.', 'quest 9476 reward text (bones upon the altar); quest 9475 description (skeleton is Featherbeard, map of Shadra''Alor and its three temples, x marks for the eggs); gameobjects 181643 Featherbeard''s Remains, 181645 Gryphon Egg x10 in area 353'),
(4714, 1, 2, 255, 'Something darker has come through the portal as well. Lethon, once among Ysera''s most trusted lieutenants and now twisted by nightmare, lurks beneath the boughs and turns on any who approach. His scales have darkened, and he wields the power of shadow.', 'warcraft.wiki.gg/wiki/Lethon; DB: Lethon 14888 spawned at Seradane (753,-4012); mod-individual-progression ipp_aware_npcs.sql (Dragons of Nightmare 14887-14890 phaseMask IPPPHASE) and IndividualProgression.cpp checkIPPhasing (AREA_SERADANE 356: IPP_PHASE cast once PROGRESSION_ONYXIA, state 2, is passed)'),
(4715, 1, 0, 255, 'Another island keeps a troll''s secret. Rin''ji, a Witherbark prisoner led out of the Quel''Danil Lodge, told of something hidden on a small island at the cliffs, and it proved to be a tablet covered in strange Witherbark markings that no one but a scholar could hope to read.', 'quest 2742 reward text (troll tablet, strange markings); quest 2782 description (Witherbark troll markings), offered from Rin''ji''s Secret 142127 on the turn-in (RewardNextQuest); creature_text 7780 (hid something on island there)'),
(4718, 1, 0, 255, 'Sharpbeak came home at last. Swiftwing and Keenclaw returned with their child and fussed over him like new parents, and the sight was enough to bring a mist to the old gryphon master''s eyes. The gryphons of Aerie Peak and their riders, he promised, would sing the name of Sharpbeak''s rescuer for a long, long time.', 'quest 2994 reward text (parents returned with their child, mist in the eyes, will sing your name; the text spells Swiftwind)'),
(4720, 1, 0, 255, 'The key to the elder''s shackles was taken from Hitah''ya the Keeper in a cave nearby, and Elder Torntusk walked free. He promised that the Revantusk would know of the deed, and sent word ahead to his mate that he was coming home to her.', 'quest 7846 description and reward text (Hitah''ya, freedom at last, Revantusk will know your deeds); quest 7847 description (tell her that I am coming home), offered on the turn-in of 7846 (RewardNextQuest); creature_text 14757 (I come home soon, my dear)'),
(4720, 2, 0, 255, 'When the vessels were brought to her, Primal Torntusk lifted the dark energy that compels the Vilebranch, but only for now. The Revantusk must stay ever vigilant, she warns, for even if the Vile Priestess is destroyed, another will soon take her place.', 'quest 7850 reward text'),
(4722, 1, 0, 255, 'Hexx holds more than her tribe''s devotion. When Thadius Grimshade''s divination went looking for the stolen gryphon Sharpbeak, it found him caged high on a cliff at the top of Jintha''Alor, and the key to that cage in the hands of the Vile Priestess.', 'quest 2993 description (cage high on a cliff, key held by Vile Priestess Hexx), offered by Grimshade on the turn-in of 2992 (RewardNextQuest)'),
(4722, 2, 0, 255, 'The Revantusk have their own cause against her. When the Vilebranch carried off Elder Torntusk in a midnight raid, he was taken to the top of Jintha''Alor, where Hexx is said to be preparing him as a sacrifice to the faceless blood god.', 'quest 7845 description'),
(4723, 1, 0, 255, 'Jammal''an''s head brought him revenge but no comfort. The prophet''s reckless trust in false visions, the exile said, had led the Atal''ai to their eternal doom. He gave thanks that his exile was avenged and mourned for his people, for there was no home left for him to return to.', 'quest 1446 reward text'),
(4724, 1, 0, 255, 'Once safely within sight of the road home, Rin''ji kept the bargain: something lay hidden on a small island at the Overlook Cliffs, and the finder could keep it. It was a tablet covered in Witherbark markings no one could read. A troll in distress might have promised anything, and whether it held something valuable or nothing at all remained a mystery.', 'creature_text 7780 (can see the road now, hid something on island, you find it you keep it); quest 2742 reward text; quest 2782 description (Witherbark markings; valuable or quite the opposite), offered from Rin''ji''s Secret on the turn-in'),
(4724, 2, 0, 255, 'The tablet went at last to Oran Snakewrithe in the Undercity, a scholar well known for her knowledge of the Witherbark. She found the tale of the deserted island very interesting indeed, put the tablet carefully away and rubbed her hands together: the Dark Lady, she said, would be very pleased with this discovery.', 'quest 2782 log text (Oran a well known scholar on the Witherbark, Magic Quarter); quest 8273 reward text (auto-complete, QuestType 0, so QUEST_DONE)'),
(4726, 1, 0, 255, 'The Witherbark cages held no gryphon. That was grim news to Talonaxe, for Sharpbeak is destined to lead the next generation of gryphons, and if he is lost the strength and spirit of the whole fleet will suffer. Perhaps the Vilebranch had him instead, and their Altar of Zul, on the western edge of their territory, was the next place to search.', 'quest 2988 reward text; quest 2989 description, offered on the turn-in of 2988 (RewardNextQuest)'),
(4726, 2, 0, 255, 'He was not atop the Altar of Zul either, which Talonaxe counted a mercy, for the Vilebranch are known for their sacrifices. With the trail cold, he sent a feather from the nest where Sharpbeak sleeps to Thadius Grimshade, a Wildhammer who left Aerie Peak long ago in pursuit of darker knowledge and now works as a diviner in Nethergarde Keep.', 'quest 2989 reward text; quest 2990 description, offered on the turn-in of 2989 (RewardNextQuest)'),
(4726, 3, 0, 255, 'Grimshade''s help came at a price, but once it was paid his ritual followed the bond between the feather and its owner. Sharpbeak was held in a cage high on a cliff at the top of Jintha''Alor, the Vilebranch capital, and the key to the cage was in the hands of Vile Priestess Hexx herself.', 'quest 2992 description and reward text (connection between feather and owner; the ritual was a success); quest 2993 description, offered on the turn-in of 2992 (RewardNextQuest)'),
(4726, 4, 0, 255, 'Champions fought their way to the summit of Jintha''Alor, took the key from the Vile Priestess and set Sharpbeak free. His parents, Swiftwing and Keenclaw, brought him home and fussed over him like new parents, and Talonaxe swore that the gryphons of Aerie Peak and their riders would sing the rescuers'' names for a long, long time.', 'quest 2994 description and reward text; warcraft.wiki.gg/wiki/Sharpbeak (Swiftwing and Keenclaw)'),
(4727, 1, 0, 255, 'Featherbeard''s hovel stood empty. His journal told of a growing number of Witherbark raids on the aeries and a rash of stolen eggs, of a fruitless search of the smaller troll villages, and of his suspicion that Mai''jin was behind it all. Its last, hasty line said that he meant to go to Shadra''Alor in search of the eggs.', 'quest 9469 reward text; quest 9476 description, offered from the journal on the turn-in of 9469 (RewardNextQuest)'),
(4727, 2, 0, 255, 'At Shadra''Alor a heap of dwarven bones lay upon an altar, all that was left of Featherbeard. Clutched in one skeletal hand was a torn and stained sheaf of paper: a map of the city and its three temples, marked where the stolen eggs were hidden.', 'quest 9476 reward text (bones upon the altar); quest 9475 description (the skeleton is Featherbeard, the map)'),
(4727, 3, 0, 255, 'The eggs came home, but the news struck Rualeth with horror. He understood why Featherbeard had gone after them, yet wished he had taken others along. The death, he feared, would enrage Falstad Wildhammer, bring retaliation against the trolls and delay his own audience indefinitely.', 'quest 9475 reward text'),
(4728, 1, 0, 255, 'The champions climbed to the chained elder, slew Hitah''ya the Keeper in a nearby cave for the key to his shackles and set him free. Elder Torntusk vowed that the Revantusk would know their deeds and sent them ahead to tell his mate that he was coming home.', 'quests 7846, 7847 descriptions and 7846 reward text'),
(4728, 2, 0, 255, 'Malkhor''s skull and bones were recovered from the oozes and wolves near the top of the city and brought home to his brother. Markhor meant to take them to Mystic Yayo''jin to be prepared for a proper burial. He would miss his dearest brother, he said, and named the one who brought them back a true hero.', 'quest 7849 log text (refuse pit and wolf den), completion text (Yayo''jin, proper burial) and reward text'),
(4728, 3, 0, 255, 'The vessels of tainted blood were carried back to Revantusk, and Primal Torntusk lifted the dark energy that compels the Vilebranch, for now. The village must stay ever vigilant, she warned, for even if the Vile Priestess is destroyed, another soon takes her place.', 'quest 7850 reward text'),
(4728, 4, 0, 255, 'Vile Priestess Hexx and her Aman''zasi guard were slain atop Jintha''Alor, and the bounty posted in Primal Torntusk''s name was claimed. She called it a crippling blow to the Vilebranch indeed and rewarded the slayers richly.', 'quest 7861 description (by order of Primal Torntusk) and reward text'),
(4728, 5, 0, 255, 'As for the post of guard captain, those who thinned the berserkers, shadow hunters, blood drinkers and soul eaters were told that they were worthy candidates indeed, and were handed a trinket for their trouble. Primal Torntusk, it seems, will be reviewing all applications next year.', 'quest 7862 description and reward text'),
(4729, 1, 0, 255, 'The bodies were left as a warning, and Otho laughed that the Revantusk were forging new alliances of their own. He wanted a second message next. The Wildhammers and their gryphons are said to be as close as troll and mate, so the gryphons of the hills were hunted for a long and elegant feather.', 'quest 7841 reward text; quest 7842 description, offered on the turn-in of 7841 (RewardNextQuest)'),
(4729, 2, 0, 255, 'From the feather Otho made his final message: a long, blood drenched spear wrapped in gryphon feathers, to be carried into Aerie Peak itself and driven into the ground beside the well at the center of town. He hoped it would send the dwarves packing, or at least make them very, very angry.', 'quest 7842 completion and reward texts; quest 7843 description'),
(4729, 3, 0, 255, 'The spear was planted in the heart of Aerie Peak. Otho only wished he could have seen the look on the dwarves'' faces, and wondered aloud whether they were already packing their bags and leaving town. For the deed he handed over the big mojo.', 'quest 7843 reward text'),
(4730, 1, 0, 255, 'The sample went to Apothecary Lydon of Tarren Mill, who judged it the venom of some spider and wanted it fresh, so he sent for an undamaged venom sac from the broodguards that nest near Shadra''Alor. Their venom was fresh but not nearly as potent: the bottles must have come from a different spider. To learn which, he sent for the counsel of Master Gadrin of Sen''jin Village, a troll who knows the Witherbark well.', 'quest 2933 reward text (from some arachnoid creature); quest 2934 description; quest 2935 description (broodguard venom not as potent; consult Gadrin)'),
(4730, 2, 0, 255, 'Gadrin''s answer was not a welcome one. The Witherbark worship a spider god, and from her they collect their most potent venom, so whoever wants that venom must summon the god herself. To do that one must know her true name, and it lay on a tablet in Zul''Farrak, in a tomb guarded by Theka the Martyr.', 'quest 2935 reward text (you are not going to like what I have to tell you); quest 2936 description'),
(4730, 3, 0, 255, 'The tablet gave up the name, Elortha no Shadra, which Gadrin bade be spoken only in whispers, for its utterance carries great weight in the realms of the spirit. He set it into a parchment of summoning, to be read at the altar of Shadra''Alor, deep within the Witherbark realm.', 'quest 2936 reward text; quest 2937 description, offered on the turn-in of 2936 (RewardNextQuest)'),
(4730, 4, 0, 255, 'At the altar the spider god Shadra was called forth and slain, and her venom proved all Lydon had hoped: a single drop killed nearly two dozen rabbits, though some, he admitted, were very small. He sent a sample on to his superior, Master Apothecary Faranell in the Undercity, certain he would want to test it himself.', 'quest 2937 log text; quest 2938 description (two dozen rabbits, sample to Faranell); creature_template 2707 Shadra (family spider)');
